import { zoom, zoomIdentity } from 'd3-zoom'
import { select } from 'd3-selection'
import { taperedPolygonForLink } from '../layers/flow/sankey'
import { isCompact } from './layout-profile'
import { hideCollidingLabels } from './decoration/label-layout'

//types
/** @typedef {import('../types/core/MapInstance').MapInstance} MapInstance */

/**
 * @param {MapInstance} map
 */
export const defineMapZoom = function (map) {
    if (map.gridCartogram_) {
        defineGridCartogramZoom(map)
        return
    }

    // existing geographic zoom logic
    defineGeographicZoom(map)
}

function defineGridCartogramZoom(map) {
    const svg = map.svg()
    const zoomGroup = svg.select('#em-zoom-group-' + map.svgId_)

    map.__zoomBehavior = zoom()
        .scaleExtent(map.zoomExtent_ || [1, 8])
        .on('zoom', (event) => {
            zoomGroup.attr('transform', event.transform)
            map.__lastTransform = event.transform
            map.__hasZoomed = event.transform.k !== 1
            updateLegendBackgroundOpacity(map)
            map.onZoom_?.(event, map)
        })
        .on('end', (event) => {
            map.onZoomEnd_?.(event, map)
        })

    svg.call(map.__zoomBehavior)
    svg.call(map.__zoomBehavior.transform, zoomIdentity)
}

export const defineGeographicZoom = function (map) {
    const svg = select('#' + map.svgId())
    let previousT = zoomIdentity
    let panUnlocked = !map.lockPanUntilZoom_
    let snappingBack = false
    const zoomExtent = map.zoomExtent_ || [0, 0]

    // If the user allows zoom < 1 (e.g. [0.1, 10]), pad translateExtent based on kmin.
    // This keeps panning possible even when zoomed out.
    const kmin = Math.max(zoomExtent[0] || 1, 0.01)
    const needsPad = kmin < 1
    const panPadFactor = map.panPadFactor_ ?? 0.1
    const padX = needsPad ? panPadFactor * (1 / kmin - 1) * map.width_ : map.width_
    const padY = needsPad ? panPadFactor * (1 / kmin - 1) * map.height_ : map.height_

    const translateExtent = map.translateExtent_
        ? map.translateExtent_
        : needsPad
          ? [
                [-padX, -padY],
                [map.width_ + padX, map.height_ + padY],
            ]
          : [
                [0, 0],
                [map.width_, map.height_],
            ]

    map.__zoomBehavior = zoom()
        .filter((e) => !e.target.closest('.em-zoom-buttons') && !e.target.closest('.em-button'))
        .extent([
            [0, 0],
            [map.width_, map.height_],
        ])
        .scaleExtent(zoomExtent)
        .translateExtent(translateExtent)

        .on('start', (e) => {
            if (e.sourceEvent && e.sourceEvent.type !== 'wheel') {
                svg.classed('em-dragging', true)
            }
        })

        .on('zoom', (e) => {
            const t = e.transform
            const zoomGroup = map.svg_.select('#em-zoom-group-' + map.svgId_)

            if (snappingBack) {
                snappingBack = false
                return
            }

            map.__lastTransform = t

            if (t.k !== previousT.k) {
                if (map.lockPanUntilZoom_) panUnlocked = true
                zoomHandler(e, previousT, map)
                zoomGroup.attr('data-zoom', t.k).attr('transform', t)
                hideCollidingLabels(map) // measures the screen, so it needs the new transform
                previousT = t
            } else if (!map.lockPanUntilZoom_ || panUnlocked) {
                panHandler(e, map)
                zoomGroup.attr('transform', t)
                hideCollidingLabels(map)
                previousT = t
            } else {
                snappingBack = true
                svg.call(map.__zoomBehavior.transform, previousT)
            }
        })
        .on('end', (e) => {
            unfreezeStrokeWidths(map)
            svg.classed('em-dragging', false)
            map.onZoomEnd_?.(e, map)
            window.dispatchEvent(new CustomEvent('estatmap:zoomend-' + map.svgId_, { detail: map }))
        })

    map.__lastTransform = previousT

    // Compute baseline metres per pixel (k=1) from left/right edges
    if (!map.__baseZ) {
        const centerY = map.height_ / 2
        const [geoLeftX] = map._projection.invert([0, centerY])
        const [geoRightX] = map._projection.invert([map.width_, centerY])
        map.__baseZ = (geoRightX - geoLeftX) / map.width_
    }

    svg.call(map.__zoomBehavior)
    // In the compact layout a single finger scrolls the page (d3-zoom would otherwise claim every touch, trapping
    // the page under the map); a horizontal drag still pans and two fingers pinch or pan the map.
    if (isCompact(map)) svg.style('touch-action', 'pan-y')
}

export function setMapView(map, pos) {
    if (!map.svg_ || !map.__zoomBehavior) return
    const svg = map.svg_
    const zoomGroup = svg.select('#em-zoom-group-' + map.svgId_)

    const k = map.__baseZ / pos.z
    const [projX, projY] = map._projection([pos.x, pos.y])
    const tx = map.width_ / 2 - projX * k
    const ty = map.height_ / 2 - projY * k

    const newTransform = zoomIdentity.translate(tx, ty).scale(k)
    map.__programmaticZoom = { x: pos.x, y: pos.y, z: pos.z }
    map.__lastTransform = newTransform

    svg.call(map.__zoomBehavior.transform, newTransform)
    zoomGroup.attr('data-zoom', k)

    map.position_.x = pos.x
    map.position_.y = pos.y
    map.position_.z = pos.z
}

/**
 * Animate the map view to a position (same {x, y, z} as `position()`), using d3's smooth glide zoom
 * (van Wijk interpolation) so the map zooms out and in again on long moves.
 * Missing x/y/z keep their current value. A falsy `pos` returns to the initial (unzoomed) view.
 * @param {MapInstance} map
 * @param {{x?: number, y?: number, z?: number}|null} pos
 * @param {{duration?: number, ease?: (t: number) => number}} [options]
 */
export function zoomMapTo(map, pos, options = {}) {
    if (!map.svg_ || !map.__zoomBehavior || !map.__baseZ) return
    const { duration = 1500, ease, onEnd } = options

    let transform = zoomIdentity
    if (pos) {
        const cur = map.position_ || {}
        const x = pos.x ?? cur.x
        const y = pos.y ?? cur.y
        const z = pos.z ?? cur.z ?? map.__baseZ
        const k = map.__baseZ / z
        const [projX, projY] = map._projection([x, y])
        transform = zoomIdentity.translate(map.width_ / 2 - projX * k, map.height_ / 2 - projY * k).scale(k)
    }

    if (!(duration > 0)) {
        map.svg_.call(map.__zoomBehavior.transform, transform)
        onEnd?.(map)
        return
    }
    const t = map.svg_.transition().duration(duration)
    if (ease) t.ease(ease)
    // 'end' only fires if the glide completes; a newer zoomTo/zoom interrupts it silently
    if (onEnd) t.on('end', () => onEnd(map))
    t.call(map.__zoomBehavior.transform, transform)
}

/**
 * Apply the current zoom scale to labels that were (re)built while the map is already zoomed, so they get the
 * same counter-scaling as labels present during the zoom.
 * @param {MapInstance} map
 */
export function applyZoomToLabels(map) {
    const t = map.__lastTransform
    if (!t || t.k === 1) return
    if (map.labels_?.scaleOnZoom !== false) scaleLabelTexts(t, map)
    if (map.labels_?.backgrounds) scaleLabelBackgrounds(t, map)
}

/**
 * Same as applyZoomToLabels, for custom locations (points + labels) that are (re)rendered while the map is zoomed:
 * they keep a constant screen size, so they need the inverse scale straight away.
 * @param {MapInstance} map
 */
export function applyZoomToLocations(map) {
    const t = map.__lastTransform
    if (!t || t.k === 1) return
    scaleLocations(t, map)
}

const panHandler = (event, map) => {
    const t = event.transform
    const cx = (map.width_ / 2 - t.x) / t.k
    const cy = (map.height_ / 2 - t.y) / t.k
    const [geoX, geoY] = map._projection.invert([cx, cy])

    map.position_.x = geoX
    map.position_.y = geoY

    window.dispatchEvent(new CustomEvent('estatmap:zoomed-' + map.svgId_, { detail: map }))
    if (typeof map.onZoom_ === 'function') map.onZoom_(event, map) // <--- new hook. user defined
}

const zoomHandler = (event, previousT, map) => {
    const t = event.transform
    map.__hasZoomed = t.k !== 1
    updateLegendBackgroundOpacity(map)
    const cx = (map.width_ / 2 - t.x) / t.k
    const cy = (map.height_ / 2 - t.y) / t.k
    const [projectedX, projectedY] = map._projection.invert([cx, cy])

    if (map.__programmaticZoom) {
        const p = map.__programmaticZoom
        map.position_.x = p.x
        map.position_.y = p.y
        map.position_.z = p.z
        delete map.__programmaticZoom
    } else {
        map.position_.x = projectedX
        map.position_.y = projectedY
        map.position_.z = map.__baseZ / t.k
    }

    //  Store current zoom scale for later use (hover, click, etc.)
    map._lastZoomK = t.k

    freezeStrokeWidths(map) // until the zoom ends
    scaleStrokeWidths(t, map, 'flow')
    if (map.labels_?.scaleOnZoom !== false) {
        scaleLabelTexts(t, map)
    }
    if (map.labels_?.backgrounds) scaleLabelBackgrounds(t, map)
    scaleLocations(t, map)
    scalePlacenames(t, map)

    window.dispatchEvent(new CustomEvent('estatmap:zoomed-' + map.svgId_, { detail: map }))
    if (typeof map.onZoom_ === 'function') map.onZoom_(event, map) // <--- new hook. user defined
}

const updateLegendBackgroundOpacity = (map) => {
    const layers = map.layers_?.length ? map.layers_ : [map]
    layers.forEach((layer) => layer.legendObj_?.updateBackgroundBoxOpacity?.())
}

/**
 * @description adjusts text elements dynamically according to zoom
 * @param {*} transform
 */
const scaleLabelBackgrounds = function (transform, map) {
    const zoomGroup = map.svg_.select('#em-zoom-group-' + map.svgId_)
    const elements = zoomGroup.selectAll('.em-label-background')
    const zoomFactor = transform.k
    const updates = []

    elements.each(function () {
        const element = select(this)
        // Get the original width, height, x, and y from data attributes or current attributes
        const originalWidth = parseFloat(element.attr('data-width')) || parseFloat(element.attr('width'))
        const originalHeight = parseFloat(element.attr('data-height')) || parseFloat(element.attr('height'))
        const originalX = parseFloat(element.attr('data-x')) || parseFloat(element.attr('x'))
        const originalY = parseFloat(element.attr('data-y')) || parseFloat(element.attr('y'))

        // Only process elements that have valid width, height, x, and y
        if (originalWidth > 0 && originalHeight > 0 && !isNaN(originalX) && !isNaN(originalY)) {
            // Store the original width, height, x, and y for the first time if not already stored
            if (!element.attr('data-width')) {
                element.attr('data-width', originalWidth)
                element.attr('data-height', originalHeight)
                element.attr('data-x', originalX)
                element.attr('data-y', originalY)
            }

            // Calculate the target width, height, x, and y based on zoom factor (inverse scaling)
            const targetWidth = originalWidth * (1 / zoomFactor) // Inverse scaling
            const targetHeight = originalHeight * (1 / zoomFactor) // Inverse scaling
            const targetX = originalX * (1 / zoomFactor) // Adjust x position
            const targetY = originalY * (1 / zoomFactor) // Adjust y position

            // Add the style change to a batch array
            updates.push({ element, targetWidth, targetHeight, targetX, targetY })
        }
    })

    // Apply all style changes at once
    updates.forEach(({ element, targetWidth, targetHeight, targetX, targetY }) => {
        element.attr('width', targetWidth).attr('height', targetHeight).attr('x', targetX).attr('y', targetY)
    })
}
/**
 * @description adjusts text elements dynamically according to zoom
 * @param {*} transform
 */
const scaleLabelTexts = function (transform, map) {
    const zoomGroup = map.svg_.select('#em-zoom-group-' + map.svgId_)
    const labels = zoomGroup.select('#em-labels')
    const elements = labels.selectAll('*') // Select all labels
    const zoomFactor = transform.k
    const updates = []

    elements.each(function () {
        const element = select(this)

        // the original size is stored on the first zoom: no need to ask the browser for the computed style again
        let originalFontSize = parseFloat(element.attr('data-fs'))
        if (!(originalFontSize > 0)) {
            // Get font-size from inline or computed style
            const inlineFontSize = element.attr('font-size')
            const cssFontSize = window.getComputedStyle(this).fontSize
            const fontSize = inlineFontSize || cssFontSize
            // Only process elements that have a font size defined
            if (!(fontSize && parseFloat(fontSize) > 0)) return
            originalFontSize = parseFloat(inlineFontSize) || parseFloat(cssFontSize)
            // Store the original font size for the first time
            element.attr('data-fs', originalFontSize)
        }

        // Calculate the target font size based on zoom factor and add the style change to a batch array
        updates.push({ element: this, targetFontSize: originalFontSize / zoomFactor })
    })

    // Apply all style changes at once
    updates.forEach(({ element, targetFontSize }) => {
        element.style.setProperty('font-size', `${targetFontSize}px`, 'important')
    })

    // A numeric dy offset (geographic labels sit 7px above their anchor) lives in the zoomed coordinate system
    // too, so it has to shrink with the font. Otherwise the text drifts away from its background rect, which is
    // scaled as a whole by scaleLabelBackgrounds.
    labels.selectAll('text').each(function () {
        const element = select(this)
        const dy = element.attr('data-dy') ?? element.attr('dy')
        if (dy === null || !/^-?\d*\.?\d+$/.test(dy.trim())) return
        if (!element.attr('data-dy')) element.attr('data-dy', dy)
        element.attr('dy', parseFloat(dy) / zoomFactor)
    })
}

/**
 * Keep placename labels at a constant screen size while the map zooms. They live inside the zoom group, so their
 * font size is divided by the zoom factor (the halo stroke is handled by scaleStrokeWidths via data-sw).
 * Positions are untouched, so labels stay anchored to their places.
 */
const scalePlacenames = function (transform, map) {
    const zoomGroup = map.svg_.select('#em-zoom-group-' + map.svgId_)
    const k = transform.k || 1
    zoomGroup.selectAll('#em-placenames text').each(function () {
        const element = select(this)
        const base = parseFloat(element.attr('data-fs'))
        if (base > 0) element.attr('font-size', `${base / k}px`)
    })
}

/**
 * Keep custom location symbols/labels at constant screen size while map zooms.
 * Locations are rendered inside the zoom group, so we apply an inverse scale
 * on the location elements to compensate for the parent transform.
 */
const scaleLocations = function (transform, map) {
    const zoomGroup = map.svg_.select('#em-zoom-group-' + map.svgId_)
    const invScale = 1 / (transform.k || 1)
    const t = invScale === 1 ? null : `scale(${invScale})`

    zoomGroup.selectAll(`#em-locations-${map.svgId_} .em-loc-symbol`).attr('transform', t)
    zoomGroup.selectAll(`#em-locations-${map.svgId_} .em-loc-label, #em-locations-${map.svgId_} .em-loc-label-halo`).attr('transform', t)
}

/**
 * Elements whose stroke width follows the zoom, found once per set of map elements (not on every zoom event: a map has
 * thousands of them, and asking the browser for the computed style of each one is what made zooming laggy).
 * A plain element gets its width as `calc(<base>px / var(--em-zoom-k))` once, so that a zoom changes one CSS variable on
 * the zoom group instead of rewriting every element. Flow links keep their own per-event update (width and dashes).
 * The set is found again when elements are added or removed (a MutationObserver marks it stale).
 */
const getStrokeTargets = function (zoomGroup) {
    const group = zoomGroup.node()
    let cache = group.__emStrokeTargets
    if (cache && !cache.stale) return cache
    if (!cache) {
        cache = { stale: true, flow: [] }
        group.__emStrokeTargets = cache
        if (typeof MutationObserver !== 'undefined') {
            // stroke widths we set ourselves are attribute/style changes: only added or removed elements matter
            cache.observer = new MutationObserver(() => (cache.stale = true))
            cache.observer.observe(group, { childList: true, subtree: true })
        }
    }
    cache.flow = []
    // measure first, write after: writing between measurements would make the browser recalculate style for every one
    const found = []
    zoomGroup.selectAll('*').each(function () {
        // Custom locations (symbols + labels) scale naturally with zoom.
        if (this.closest && this.closest('.em-locations')) return
        const inlineStrokeWidth = this.getAttribute('stroke-width')
        const stored = parseFloat(this.getAttribute('data-sw'))
        let base = stored
        if (!(base > 0)) {
            const strokeWidth = inlineStrokeWidth || window.getComputedStyle(this).strokeWidth
            base = parseFloat(inlineStrokeWidth) || parseFloat(strokeWidth)
        }
        if (base > 0) found.push({ element: this, base, stored: stored > 0 })
    })
    found.forEach(({ element, base, stored }) => {
        if (!stored) element.setAttribute('data-sw', base)
        if (element.classList.contains('em-flow-link') || element.classList.contains('em-flow-link-outline')) {
            cache.flow.push({ element, base })
        } else {
            element.style.setProperty('stroke-width', `calc(${base}px / var(--em-zoom-k, 1))`, 'important')
        }
    })
    cache.stale = false
    // the writes above are not mutations of the set, but the observer may have queued records for them
    cache.observer?.takeRecords()
    return cache
}

/**
 * Stroke widths are the costly part of a zoom: changing them makes the browser recalculate the style of every element of
 * the map, thousands of them, which is more than a phone can do 60 times a second. So while the map is being zoomed they
 * are not changed: a CSS class (`em-zooming`, see map.css) makes the browser keep strokes at a constant screen width by
 * itself (`vector-effect: non-scaling-stroke`) and the variable behind the widths is set to 1. When the zoom ends the
 * class is removed and the variable gets the final zoom factor: two style recalculations per gesture, not one per event.
 * A pan never changes the zoom factor, so it does none.
 */
const freezeStrokeWidths = function (map) {
    if (map.__strokesFrozen) return
    map.__strokesFrozen = true
    const zoomGroup = map.svg_.select('#em-zoom-group-' + map.svgId_)
    getStrokeTargets(zoomGroup) // found now, not in the middle of the gesture
    zoomGroup.node().style.setProperty('--em-zoom-k', 1)
    map.svg_.classed('em-zooming', true)
}

const unfreezeStrokeWidths = function (map) {
    if (!map.__strokesFrozen) return
    map.__strokesFrozen = false
    map.svg_.classed('em-zooming', false)
    scaleStrokeWidths(map.__lastTransform ?? zoomIdentity, map, 'plain')
}

/**
 * @description adjusts all stroke-widths dynamically according to zoom
 * @param {*} transform
 * @param {'all'|'plain'|'flow'} [part] plain elements (a variable, see getStrokeTargets), flow links, or both
 */
const scaleStrokeWidths = function (transform, map, part = 'all') {
    const zoomGroup = map.svg_.select('#em-zoom-group-' + map.svgId_)
    const zoomFactor = transform.k
    const targets = getStrokeTargets(zoomGroup)

    // one variable for every plain element (see getStrokeTargets)
    if (part !== 'flow') zoomGroup.node().style.setProperty('--em-zoom-k', zoomFactor)
    // flow links and tapered ribbons are few, and their geometry has to follow every event
    if (part === 'plain') return

    targets.flow.forEach(({ element, base }) => {
        const el = select(element)
        el.attr('stroke-width', base / zoomFactor)

        // Rescale dasharray from original stored values
        const baseDashVis = parseFloat(el.attr('data-dash-vis'))
        const baseDashGap = parseFloat(el.attr('data-dash-gap'))
        if (!isNaN(baseDashVis) && !isNaN(baseDashGap)) {
            el.attr('stroke-dasharray', `${baseDashVis / zoomFactor} ${baseDashGap / zoomFactor}`)
        }
    })

    // ── rescale tapered sankey polygons ─────────────────────────────────
    zoomGroup.selectAll('.em-flow-link-tapered[data-center-path], .em-flow-link-outline[data-center-path]').each(function () {
        const el = select(this)
        const dCenter = el.attr('data-center-path')
        const baseWidth = parseFloat(el.attr('data-link-width'))
        const isOutline = el.attr('data-is-outline') === 'true'
        const outlineWidth = parseFloat(el.attr('data-outline-width')) || 0

        if (!dCenter || !baseWidth) return

        const scaledWidth = baseWidth / zoomFactor
        const extraPad = isOutline ? outlineWidth / zoomFactor : 0

        // Reconstruct a fake link object with scaled width
        const scaledLink = { width: scaledWidth }

        const dPoly = taperedPolygonForLink(
            scaledLink,
            () => dCenter,
            {
                startRatio: 1, // flat start for non-gradient sankey
                samples: 48,
                minStartWidth: scaledWidth,
                pointedTip: el.attr('data-pointed-tip') === 'true',
            },
            extraPad
        )

        el.attr('d', dPoly)
    })
}
