.em--compact .em-legend-subtitle {
    font-size: 13px;
}

.em--compact .em-inset-title {
    font-size: 14px;
}

.em--compact .em-inset-subtitle {
    font-size: 12px;
}

.em--compact .em-button text {
    font-size: 22px;
}

/* The tooltip is a page element, outside the map, so it follows the window. */
@media (max-width: 768px) {
    /* Prevent the tooltip from being taller than half the screen,
       and ensure it never bleeds past either edge */
    .em-tooltip {
        --em-tooltip-max-width: min(150px, 72vw);
        --em-tooltip-max-height: 45vh;
        /* Slightly larger shadow so it reads clearly over a map */
        box-shadow:
            0px 6px 12px rgba(0, 0, 0, 0.18),
            0px 2px 4px rgba(0, 0, 0, 0.12);
    }

    .em-tooltip-bar {
        padding: 8px 10px;
        font-size: 12px;
        line-height: 1.3;
        /* Wrap long region names rather than forcing a wide box */
        word-break: break-word;
    }

    .em-tooltip-text {
        padding: 6px 10px;
        font-size: 13px;
        line-height: 1.4;
    }

    .em-tooltip-breakdown {
        gap: 0px; /* More breathing room between rows on touch */
        padding: 8px 10px;
        padding-top: 4px;
