    .em-breakdown-value {
        margin-left: 10px;
    }

    /* Stacked bar SVG: stretch to fill the tooltip width instead of
       rendering at the fixed \`tw\` pixel value baked into the HTML */
    .em-tooltip-barchart-container svg {
        width: 100%;
        height: auto;
    }

    /* Compact the cx (trivariate) table on small screens */
